import{_ as a,o as n,a as t,b as p}from"./app.C41L12d5.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/advanced_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/advanced_optimization.md","outlineHeaders":[{"level":2,"title":"残余瓶颈分析","slug":"残余瓶颈分析","link":"#残余瓶颈分析"},{"level":2,"title":"极致打磨手段","slug":"极致打磨手段","link":"#极致打磨手段"},{"level":3,"title":"极限调优A：L2 Cache bypass","slug":"极限调优A：L2-Cache-bypass","link":"#极限调优A：L2-Cache-bypass"},{"level":3,"title":"极限调优B：消除UB Bank Conflict","slug":"极限调优B：消除UB-Bank-Conflict","link":"#极限调优B：消除UB-Bank-Conflict"},{"level":2,"title":"终极性能达成","slug":"终极性能达成","link":"#终极性能达成"}],"lastUpdated":1787050286000}'),e={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/add_vector_operator/advanced_optimization.md"};function c(l,s,o,r,i,d){return n(),t("div",null,[...s[0]||(s[0]=[p(`<div><article class="markdown-body"><h1>高阶性能打磨<span id="ZH-CN_TOPIC_000000_ADD_ADV"></span></h1><p>本节在中级性能优化的基础上，介绍Add算子的高阶极限打磨方法。</p><h2 id="残余瓶颈分析">残余瓶颈分析<a class="header-anchor" href="#残余瓶颈分析">​</a></h2><p>中级优化后（Case 4），端到端耗时264.02μs，MTE2利用率97.3%，搬运与计算已实现流水并行。残余瓶颈主要体现在：</p><ul><li><strong>瓶颈1：L2 Cache污染</strong>：Add输入数据只读取一次（流式访问），但默认经过L2 Cache，增加了不必要的Cache开销和搬运延时。</li><li><strong>瓶颈2：Unified Buffer（UB） Bank Conflict</strong>：向量指令同时读写同一Bank Group内的数据，产生读写冲突和读读/写写冲突，导致访存串行化，向量指令效率降低。</li></ul><h2 id="极致打磨手段">极致打磨手段<a class="header-anchor" href="#极致打磨手段">​</a></h2><h3 id="极限调优A：L2-Cache-bypass">极限调优A：L2 Cache bypass<a class="header-anchor" href="#极限调优A：L2-Cache-bypass">​</a></h3><p><strong>原理</strong>：L2 Cache是AI Core和HBM之间的缓存层，适合需要重复访问的数据。对于Add算子这种流式访问场景（输入数据只读取一次），数据经过L2 Cache反而会占用Cache空间（Cache污染），增加搬运延时。通过<a href="../../../../../api/SIMD-API/basic_api/data_structures/GlobalTensor/SetL2CacheHint.html">SetL2CacheHint</a>设置<code>CACHE_MODE_DISABLE</code>，让数据绕过L2 Cache直接从GM载入UB。</p><p><strong>优化方案</strong>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 设置L2 Cache bypass：对流式访问数据禁用L2 Cache</span>
<span class="n">xGm</span><span class="p">.</span><span class="n">SetL2CacheHint</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheMode</span><span class="o">::</span><span class="n">CACHE_MODE_DISABLE</span><span class="p">);</span>
<span class="n">yGm</span><span class="p">.</span><span class="n">SetL2CacheHint</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">CacheMode</span><span class="o">::</span><span class="n">CACHE_MODE_DISABLE</span><span class="p">);</span>
</code></pre></div><p>性能提升：Case 4→Case 5，端到端耗时从264.02μs降至187.68μs，减少<strong>28.9%</strong>；MTE2耗时从250.528μs降至175.997μs，减少<strong>29.8%</strong>。</p><h3 id="极限调优B：消除UB-Bank-Conflict">极限调优B：消除UB Bank Conflict<a class="header-anchor" href="#极限调优B：消除UB-Bank-Conflict">​</a></h3><p><strong>原理</strong>：针对Atlas A2/A3系列产品，UB的大小为192KB，包含16个Bank Group，每个Bank Group包含3个Bank。向量指令一拍读取256B数据（即同时读取8个block），当xPing和yPing的起始地址落在同一Bank Group时，会产生读写冲突和读读/写写冲突，导致访存串行化。</p><p><strong>优化方案</strong>：通过调整<code>dataCopyLen</code>（16384→16256）使xPing和yPing的起始地址错开256B，确保vec指令一拍访存的数据分布在不同Bank Group，有效消解Bank Conflict。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 优化后的地址布局（避免Bank Conflict）</span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">xAddrPingBC</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">yAddrPingBC</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">BANK_CONFLICT_DATA_COPY_LEN</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">);</span><span class="w">  </span><span class="c1">// 错开256B；注意：sizeof(half)=2B，float场景需调整为sizeof(float)</span>
<span class="k">static</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">xAddrPongBC</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">MAX_DATA_COPY_LEN</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="c1">// ...</span>
</code></pre></div><p>性能提升：Case 5→Case 6，向量指令耗时从12.846μs降至6.954μs，减少<strong>45.9%</strong>；端到端耗时从187.68μs降至184.52μs，减少<strong>1.7%</strong>。</p><h2 id="终极性能达成">终极性能达成<a class="header-anchor" href="#终极性能达成">​</a></h2><table><thead><tr><th align="left">指标</th><th align="center">Case 0（入门基准）</th><th align="center">Case 4（中级优化）</th><th align="center">Case 6（高阶打磨）</th></tr></thead><tbody><tr><td align="left">Task Duration(μs)</td><td align="center">1239689.1</td><td align="center">264.02</td><td align="center"><strong>184.52</strong></td></tr><tr><td align="left">aiv_vec_time(μs)</td><td align="center">0.015</td><td align="center">12.846</td><td align="center"><strong>6.954</strong></td></tr><tr><td align="left">aiv_mte2_ratio</td><td align="center">0.005</td><td align="center">0.973</td><td align="center"><strong>0.961</strong></td></tr><tr><td align="left">端到端提升</td><td align="center">1x</td><td align="center">4695x</td><td align="center"><strong>6711x</strong></td></tr></tbody></table><p><strong>关键验证指标</strong>：</p><ul><li>端到端耗时从入门版的1.24秒降至<strong>184.52μs</strong>，提升<strong>6711倍</strong></li><li>向量指令耗时从12.846μs降至<strong>6.954μs</strong>，接近Atlas A2训练系列48核理论vector耗时5.904μs</li><li>Case 6的读写混合带宽达到<strong>2.3456 TB/s</strong>，接近硬件带宽上限</li></ul><p><strong>最终结论</strong>：Add算子经过入门→中级→高阶三级优化，端到端性能提升6711倍。当前瓶颈主要在搬运带宽本身，向量计算已接近理论极限。对于Ascend 950系列产品，Bank排列方式不同，无需Bank Conflict优化，Case 5即为最优版本。</p><p>详细内容请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/00_vector_compute/add_high_performance/README.md#%E9%AB%98%E9%98%B6%E6%80%A7%E8%83%BD%E6%89%93%E7%A3%A8">Add性能调优样例 Case 5-6</a>。</p></article></div>`,1)])])}const _=a(e,[["render",c]]);export{g as __pageData,_ as default};
